\begin{tikzpicture}[font=\sffamily, line cap=round, line join=round]
  \coordinate (O) at (0,0);
  \coordinate (A) at (7,0);
  \coordinate (B) at (0,4.04);
  % incline
  \draw[thick] (O) -- (A) -- (B) -- cycle;
  % pulley at the top of the plane
  \draw[thick] (B) circle (0.5);
  % block of 4.0 kg on the plane
  \draw[thick] (4.835,1.25) -- (3.796,1.85) -- (4.296,2.716) -- (5.335,2.116) -- cycle;
  \node at (4.57,2.0) {4.0 kg};
  % string from block over pulley, parallel to the plane
  \draw[thick] (4.046,2.283) -- (0.25,4.473);
  % string down to hanging mass
  \draw[thick] (-0.5,4.04) -- (-0.5,2.0);
  % hanging mass of 3.0 kg
  \draw[thick] (-0.85,1.0) rectangle (-0.15,2.0);
  \node[left] at (-0.95,1.5) {3.0 kg};
  % 30 degree angle at the bottom of the plane
  \pic[draw, thick, "$30^\circ$", angle radius=0.9cm, angle eccentricity=1.5] {angle=O--A--B};
  % caption
  \node[below] at (3.5,-0.9) {\textbf{Fig. 1.1}};
\end{tikzpicture}

